class Solution:
    def maxFreq(self, s: str, maxLetters: int, minSize: int, maxSize: int) -> int:
        freq_map = collections.defaultdict(int)
        max_freq = 0

        # We ONLY need to check windows of length exactly 'minSize'
        for i in range(len(s) - minSize + 1):
            sub = s[i:i + minSize]

            # If the number of unique characters is within the limit
            if len(set(sub)) <= maxLetters:
                freq_map[sub] += 1

                # Keep track of the maximum frequency seen so far
                if freq_map[sub] > max_freq:
                    max_freq = freq_map[sub]

        return max_freq

class Solution:
    def removeDuplicates(self, s: str, k: int) -> str:
        # Stack stores pairs of [character, frequency]
        stack = []

        for char in s:
            if stack and stack[-1][0] == char:
                stack[-1][1] += 1
            else:
                stack.append([char, 1])

            # If the top group reaches exactly size k, remove it
            if stack[-1][1] == k:
                stack.pop()

        # Reconstruct the final string from the stack
        return "".join(char * count for char, count in stack)

