class Solution:
    def totalFruit(self, tree: List[int]) -> int:
        count = defaultdict(int)
        left = 0
        ans = 0

        for right, fruit in enumerate(tree):
            count[fruit] += 1

            # Keep shrinking until the window has at most 2 fruit types
            while len(count) > 2:
                count[tree[left]] -= 1
                if count[tree[left]] == 0:
                    del count[tree[left]]
                left += 1

            ans = max(ans, right - left + 1)

        return ans

