                    left = mid + 1
                else:
                    right = mid - 1

        return False

class Solution:
    def maxDistance(self, position: List[int], m: int) -> int:
        position.sort()

        def can_place(dist: int) -> bool:
            count = 1
            last = position[0]

            for x in position[1:]:
                if x - last >= dist:
                    count += 1
                    last = x
                    if count >= m:
                        return True

            return False

        left, right = 1, position[-1] - position[0]
        ans = 1

