class Solution:
    def makesquare(self, nums: List[int]) -> bool:
        if not nums or len(nums) < 4:
            return False

        total = sum(nums)
        if total % 4 != 0:
            return False

        target = total // 4
        nums.sort(reverse=True)

        # If the largest stick is longer than one side, impossible
        if nums[0] > target:
            return False

        sides = [0, 0, 0, 0]

        def dfs(index: int) -> bool:
            if index == len(nums):
                return sides[0] == sides[1] == sides[2] == sides[3] == target

            used_lengths = set()
            for i in range(4):
                # Symmetry pruning: same current side length => same state
                if sides[i] in used_lengths:
                    continue
                if sides[i] + nums[index] > target:
                    continue

                used_lengths.add(sides[i])
                sides[i] += nums[index]
                if dfs(index + 1):
                    return True
                sides[i] -= nums[index]

                # If we tried putting it on an empty side and failed,
                # there is no need to try other empty sides.
                if sides[i] == 0:
                    break

            return False

        return dfs(0)

from functools import lru_cache


class Solution:
    def maxJumps(self, arr: List[int], d: int) -> int:
        n = len(arr)

        @lru_cache(None)
        def dfs(i: int) -> int:
            best = 1  # Count the current index itself

            # Try jumping to the right
            for j in range(i + 1, min(n, i + d + 1)):
                if arr[j] >= arr[i]:
                    break  # Barrier blocks any farther jump in this direction
                best = max(best, 1 + dfs(j))

            # Try jumping to the left
            for j in range(i - 1, max(-1, i - d - 1), -1):
                if arr[j] >= arr[i]:
                    break
                best = max(best, 1 + dfs(j))

            return best

        return max(dfs(i) for i in range(n))

class Solution:
    def minCostToMoveChips(self, position: List[int]) -> int:
        odd = 0
        even = 0

        for x in position:
            if x % 2 == 0:
                even += 1
            else:
                odd += 1

        # Gather on odd => pay for all even chips
        # Gather on even => pay for all odd chips
        return min(odd, even)

class Solution:
    def lemonadeChange(self, bills: List[int]) -> bool:
        five = 0
        ten = 0

        for bill in bills:
            if bill == 5:
                five += 1
            elif bill == 10:
                if five == 0:
                    return False
                five -= 1
                ten += 1
            else:  # bill == 20
                # Greedy: prefer 10 + 5 over 5 + 5 + 5
                if ten > 0 and five > 0:
                    ten -= 1
                    five -= 1
                elif five >= 3:
                    five -= 3
                else:
                    return False

        return True

