class Solution:
    def climbStairs(self, n: int) -> int:
        # Base cases: directly known answers
        if n <= 2:
            return n

        # prev2 = ways to reach step i-2
        # prev1 = ways to reach step i-1
        prev2, prev1 = 1, 2

        for _ in range(3, n + 1):
            curr = prev1 + prev2
            prev2 = prev1
