class Solution:
    def mincostTickets(self, days: List[int], costs: List[int]) -> int:
        travel_days = set(days)
        dp = [0] * 366

        for day in range(1, 366):
            if day not in travel_days:
                # No travel today, so cost does not increase
                dp[day] = dp[day - 1]
            else:
                # Try all three ticket types
                one_day = dp[max(0, day - 1)] + costs[0]
                seven_day = dp[max(0, day - 7)] + costs[1]
                thirty_day = dp[max(0, day - 30)] + costs[2]
                dp[day] = min(one_day, seven_day, thirty_day)

        return dp[365]

class Solution:
    def longestCommonSubsequence(self, text1: str, text2: str) -> int:
        n, m = len(text1), len(text2)
        dp = [[0] * (m + 1) for _ in range(n + 1)]

        for i in range(1, n + 1):
            for j in range(1, m + 1):
                if text1[i - 1] == text2[j - 1]:
                    # Matching characters can extend the previous LCS
                    dp[i][j] = dp[i - 1][j - 1] + 1
                else:
                    # Otherwise, skip one character from either string
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

        return dp[n][m]
